/**
 * In-browser Python (Pyodide / WebAssembly).
 * Runs the standard library and NumPy. Code that needs anything else (PyTorch, SciPy,
 * Transformers, ...) is NOT run: the learner gets a clear message to run it locally.
 * Output is never simulated or generated by a language model.
 */

let pyodideInstance: any = null;
let pyodideLoadingPromise: Promise<any> | null = null;

export interface PyExecutionResult {
  stdout: string;
  stderr: string;
  executionTimeMs: number;
  success: boolean;
  engine: 'WASM (Python 3.12)';
  error?: string;
  /** True when the code was not executed because it needs packages the browser runner lacks. */
  notRun?: boolean;
}

// Packages the browser runner cannot provide (it only loads NumPy).
const BROWSER_UNSUPPORTED = [
  'torch', 'transformers', 'vllm', 'faiss', 'triton', 'sentence_transformers', 'langchain',
  'llama_index', 'scipy', 'sklearn', 'jax', 'cupy', 'onnx', 'datasets', 'tiktoken',
];

const PIP_NAME: Record<string, string> = {
  sklearn: 'scikit-learn',
  sentence_transformers: 'sentence-transformers',
  llama_index: 'llama-index',
  PIL: 'pillow',
};

/** Top-level modules imported by `code` that the browser runner cannot run. */
export function findUnsupportedImports(code: string): string[] {
  const found = new Set<string>();
  for (const m of code.matchAll(/^\s*(?:import|from)\s+([A-Za-z_][A-Za-z0-9_]*)/gm)) {
    if (BROWSER_UNSUPPORTED.includes(m[1])) found.add(m[1]);
  }
  return [...found];
}

function notRunResult(modules: string[], startTime: number): PyExecutionResult {
  const pip = modules.map((m) => PIP_NAME[m] || m).join(' ');
  return {
    stdout: '',
    stderr:
      `Not run. The in-browser Python only has the standard library and NumPy, and this code needs: ${modules.join(', ')}.\n` +
      `Copy it and run it on your own machine:\n  pip install ${pip}\n  python main.py`,
    executionTimeMs: Math.round((performance.now() - startTime) * 10) / 10,
    success: false,
    notRun: true,
    engine: 'WASM (Python 3.12)',
  };
}

export async function loadPyodideEngine(): Promise<any> {
  if (pyodideInstance) {
    return pyodideInstance;
  }

  if (pyodideLoadingPromise) {
    return pyodideLoadingPromise;
  }

  pyodideLoadingPromise = new Promise(async (resolve, reject) => {
    try {
      if (!(window as any).loadPyodide) {
        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/pyodide/v0.26.1/full/pyodide.js';
        script.async = true;
        document.head.appendChild(script);

        await new Promise((res, rej) => {
          script.onload = res;
          script.onerror = () => rej(new Error('Failed to load Pyodide WebAssembly script.'));
        });
      }

      const pyodide = await (window as any).loadPyodide({
        indexURL: 'https://cdn.jsdelivr.net/pyodide/v0.26.1/full/'
      });

      await pyodide.runPythonAsync(`
import sys
import io

class OutputCapture:
    def __init__(self):
        self.stdout_io = io.StringIO()
        self.stderr_io = io.StringIO()
    
    def start(self):
        self.stdout_io = io.StringIO()
        self.stderr_io = io.StringIO()
        sys.stdout = self.stdout_io
        sys.stderr = self.stderr_io
        
    def finish(self):
        sys.stdout = sys.__stdout__
        sys.stderr = sys.__stderr__
        return self.stdout_io.getvalue(), self.stderr_io.getvalue()

_output_capture = OutputCapture()
`);

      pyodideInstance = pyodide;
      resolve(pyodide);
    } catch (err) {
      pyodideLoadingPromise = null;
      reject(err);
    }
  });

  return pyodideLoadingPromise;
}

export async function runPythonCode(code: string): Promise<PyExecutionResult> {
  const startTime = performance.now();

  // Packages the browser runner cannot provide: say so instead of pretending to run the code.
  const unsupported = findUnsupportedImports(code);
  if (unsupported.length > 0) {
    return notRunResult(unsupported, startTime);
  }

  // Run in the client-side WASM interpreter (Pyodide)
  try {
    const pyodide = await loadPyodideEngine();

    if (code.includes('import numpy') || code.includes('from numpy')) {
      await pyodide.loadPackage('numpy');
    }

    await pyodide.runPythonAsync('_output_capture.start()');

    let execError: string | null = null;
    try {
      await pyodide.runPythonAsync(code);
    } catch (err: any) {
      execError = err.message || String(err);
    }

    const captureResult = await pyodide.runPythonAsync('_output_capture.finish()');
    const [stdout, stderr] = captureResult.toJs ? captureResult.toJs() : captureResult;

    const endTime = performance.now();
    const executionTimeMs = Math.round((endTime - startTime) * 10) / 10;

    // A known package the runner does not ship: say so. Any other ImportError is a real
    // traceback (lessons about imports show them on purpose), so it is passed through untouched.
    const missing = execError && execError.match(/No module named '([^'.]+)/);
    if (missing && BROWSER_UNSUPPORTED.includes(missing[1])) {
      return notRunResult([missing[1]], startTime);
    }

    if (execError) {
      const cleanError = execError.replace(/File "<exec>", /g, 'File "main.py", ');
      return {
        stdout: stdout || '',
        stderr: stderr ? `${stderr}\n${cleanError}` : cleanError,
        executionTimeMs,
        success: false,
        engine: 'WASM (Python 3.12)',
        error: cleanError
      };
    }

    return {
      stdout: stdout || (stderr ? '' : '>>> Process executed successfully with 0 output.'),
      stderr: stderr || '',
      executionTimeMs,
      success: true,
      engine: 'WASM (Python 3.12)'
    };
  } catch (err: any) {
    // Pyodide failed to load (offline, blocked CDN) or crashed.
    return {
      stdout: '',
      stderr: `The in-browser Python could not start: ${err?.message || String(err)}\nCheck your connection, or copy the code and run it locally.`,
      executionTimeMs: Math.round((performance.now() - startTime) * 10) / 10,
      success: false,
      engine: 'WASM (Python 3.12)',
      error: err?.message || String(err),
    };
  }
}
